              [6, 6, 6, 6, 6, 6, 6, 6, 5, 6, 6, 6, 6, 6],
              [6, 6, 6, 6, 6, 6, 6, 6, 5, 6, 6, 6, 6, 6]]

# Find 5s and visualize the structure better
# Identify the two "arms" and "legs"
print("Positions of 5s:")
for r in range(len(test_input)):
    row_str = ''
    for c in range(len(test_input[0])):
        if test_input[r][c] == 5:
            row_str += 'X'
        else:
            row_str += '.'
    print(f"Row {r}:   {row_str}")

# Let me also verify my hypothesis: cells with exactly 3 adjacent special cells
print("\nCells with exactly 3 adjacent 5s:")
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if test_input[r][c] == 6:
            adj = 0
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                if 0 <= r+dr < len(test_input) and 0 <= c+dc < len(test_input[0]):
                    if test_input[r+dr][c+dc] == 5:
                        adj += 1
            if adj == 3:
                print(f"  ({r},{c})")

